({ view }) => {
          if (view !== "sources" && !isReadingView(view))
            throw Error("Unknown reading view");
          setView(view === "sources" ? "sources" : "lesson");
          if (isReadingView(view)) setTab(view);
          return { view };
        }

({ query }) => {
          if (typeof query !== "string" || query.length > 200)
            throw Error("Invalid query");
          setQuery(query);
